import random, collections, itertools, math, time

def girth_ok(n, edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    g=999
    for s in range(n):
        dist=[-1]*n; par=[-1]*n; dist[s]=0
        q=collections.deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g, dist[u]+dist[v]+1)
    return g>=7, g if g<999 else None

def dist_between(n, adj, s,t, maxd=5):
    # return <=maxd if found, else inf
    if s==t: return 0
    seen={s}; q=collections.deque([(s,0)])
    while q:
        u,d=q.popleft()
        if d>=maxd: continue
        for v in adj[u]:
            if v==t: return d+1
            if v not in seen:
                seen.add(v); q.append((v,d+1))
    return 999

def greedy_once(n=24, parts=None, target=33):
    if parts is None:
        parts=[list(range(0,8)), list(range(8,16)), list(range(16,24))]
    color={v:i for i,P in enumerate(parts) for v in P}
    candidates=[(u,v) for u in range(n) for v in range(u+1,n) if color[u]!=color[v]]
    random.shuffle(candidates)
    adj=[set() for _ in range(n)]
    edges=[]
    # Use randomized iterations selecting possible edge until stuck
    while True:
        possible=[]
        for u,v in candidates:
            if v in adj[u]: continue
            if dist_between(n, adj, u,v,5)>=6:
                possible.append((u,v))
        if not possible: break
        # choose with heuristic? random
        # prefer endpoints low degree?
        if random.random()<0.8:
            # sample some, choose min degree sum maybe max? 
            sample=random.sample(possible, min(len(possible), 20))
            # choose random weighted toward low deg
            #edge=min(sample, key=lambda e: len(adj[e[0]])+len(adj[e[1]]))
            edge=random.choice(sample)
        else:
            edge=random.choice(possible)
        u,v=edge; adj[u].add(v); adj[v].add(u); edges.append(edge)
        if len(edges)>=target:
            return edges, True
    return edges, False

start=time.time(); best=[]; bestparts=None
for trial in range(20000):
